# Generated by manage.py generate_test_cases.
from django.contrib.auth import get_user_model
from django.http import HttpResponse

from bloomerp.communication.builtins.instant_messaging.access import IMAccessManager
from bloomerp.communication.builtins.instant_messaging.controller import IMController
from bloomerp.models.communication.instant_messaging import IMMessage
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestGroupMembersComponent(BloomerpComponentTestCase):
    """Exercise roles, membership history and authorization through the generated case."""

    view_name = "components_im_group_members"

    def prepare_group(self, scenario: RequestScenario) -> None:
        """Create an owned group with a normal member and another staff user."""
        self.other = get_user_model().objects.create(
            username="group_other", is_staff=True
        )
        self.chat = IMController(self.admin_user).create_internal_group(
            "Team", [str(self.normal_user.pk), str(self.other.pk)]
        )
        scenario.view_kwargs = {"conversation_id": self.chat.pk}
        scenario.data = {**(scenario.data or {}), "user_id": str(self.normal_user.pk)}

    def prepare_admin(self, scenario: RequestScenario) -> None:
        """Give a member admin authority while retaining the creator as owner."""
        self.prepare_group(scenario)
        member = self.chat.participants.get(user=self.normal_user)
        member.role = "admin"
        member.save(update_fields=["role"])
        scenario.data["user_id"] = str(self.admin_user.pk)

    def prepare_name_patch(self, scenario: RequestScenario) -> None:
        """Prepare an SDK-shaped JSON name patch for a regular staff administrator."""
        self.prepare_admin(scenario)
        scenario.data.pop("user_id", None)

    def prepare_owner_patch(self, scenario: RequestScenario) -> None:
        """Give a non-superuser ownership before submitting the SDK name patch."""
        self.prepare_name_patch(scenario)
        IMController(self.admin_user).update_internal_group(
            self.chat.pk, "transfer", user_id=str(self.normal_user.pk)
        )

    def prepare_member_patch(self, scenario: RequestScenario) -> None:
        """Prepare a regular member's denied SDK rename attempt."""
        self.prepare_group(scenario)
        scenario.data.pop("user_id", None)

    def prepare_rejoin(self, scenario: RequestScenario) -> None:
        """Retain a departed participant's original message attribution on re-add."""
        self.prepare_group(scenario)
        member = self.chat.participants.get(user=self.normal_user)
        IMMessage.objects.create(
            conversation=self.chat, sender=member, sequence=1, body="History"
        )
        IMController(self.admin_user).update_internal_group(
            self.chat.pk, "remove", user_id=str(self.normal_user.pk)
        )

    def validate_removed(self, response: HttpResponse) -> bool:
        """Check removal revokes conversation access without deleting membership."""
        return self.chat.participants.get(
            user=self.normal_user
        ).left_at is not None and not IMAccessManager(
            self.normal_user
        ).has_access_to_conversation(self.chat)

    def validate_transfer(self, response: HttpResponse) -> bool:
        """Ensure ownership moves atomically and the former owner remains an admin."""
        return (
            self.chat.participants.filter(role="owner", left_at__isnull=True).count()
            == 1
            and self.chat.participants.get(user=self.normal_user).role == "owner"
            and self.chat.participants.get(user=self.admin_user).role == "admin"
        )

    def validate_rejoin(self, response: HttpResponse) -> bool:
        """Check rejoining preserves messages and restores access without duplicate membership."""
        member = self.chat.participants.get(user=self.normal_user)
        return (
            member.left_at is None
            and member.role == "member"
            and IMMessage.objects.get(conversation=self.chat).sender_id == member.pk
        )

    def validate_renamed(self, response: HttpResponse) -> bool:
        """Verify administrators can rename the group."""
        self.chat.refresh_from_db()
        return self.chat.name == "Renamed"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover membership roles, ownership safeguards and retained history."""
        return [
            RequestScenario(
                name="SDK rename by non-superuser admin",
                user=self.normal_user, method="PATCH", content_type="application/json",
                prepare=self.prepare_name_patch, data={"name": "Renamed"},
                expected=ExpectedResult(response_validators=[
                    self.validate_renamed, self.json_key_equals("name", "Renamed"),
                ]),
            ),
            RequestScenario(
                name="SDK rename by non-superuser owner",
                user=self.normal_user, method="PATCH", content_type="application/json",
                prepare=self.prepare_owner_patch, data={"name": "Renamed"},
                expected=ExpectedResult(response_validators=[self.validate_renamed]),
            ),
            RequestScenario(
                name="SDK rename denied to regular member",
                user=self.normal_user, method="PATCH", content_type="application/json",
                prepare=self.prepare_member_patch, data={"name": "Denied"},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="SDK rejects empty group name",
                user=self.normal_user, method="PATCH", content_type="application/json",
                prepare=self.prepare_name_patch, data={"name": "  "},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="SDK cannot change group roles",
                user=self.normal_user, method="PATCH", content_type="application/json",
                prepare=self.prepare_name_patch, data={"name": "Renamed", "action": "transfer"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Members see group roster",
                user=self.normal_user,
                prepare=self.prepare_group,
                expected=ExpectedResult(
                    response_validators=[self.contains_text("Leave group")]
                ),
            ),
            RequestScenario(
                name="Member cannot rename",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_group,
                data={"action": "rename", "name": "Denied"},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Owner transfers ownership",
                user=self.admin_user,
                method="POST",
                prepare=self.prepare_group,
                data={"action": "transfer"},
                expected=ExpectedResult(response_validators=[self.validate_transfer]),
            ),
            RequestScenario(
                name="Owner cannot leave",
                user=self.admin_user,
                method="POST",
                prepare=self.prepare_group,
                data={"action": "leave"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Transfer ownership before leaving")
                    ]
                ),
            ),
            RequestScenario(
                name="Admin cannot remove owner",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_admin,
                data={"action": "remove"},
                expected=ExpectedResult(
                    response_validators=[self.contains_text("Use leave or transfer")]
                ),
            ),
            RequestScenario(
                name="Admin can rename",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_admin,
                data={"action": "rename", "name": "Renamed"},
                expected=ExpectedResult(response_validators=[self.validate_renamed]),
            ),
            RequestScenario(
                name="Owner removes member",
                user=self.admin_user,
                method="POST",
                prepare=self.prepare_group,
                data={"action": "remove"},
                expected=ExpectedResult(response_validators=[self.validate_removed]),
            ),
            RequestScenario(
                name="Member leaves",
                user=self.normal_user,
                method="POST",
                prepare=self.prepare_group,
                data={"action": "leave"},
                expected=ExpectedResult(response_validators=[self.validate_removed]),
            ),
            RequestScenario(
                name="Rejoin preserves attribution",
                user=self.admin_user,
                method="POST",
                prepare=self.prepare_rejoin,
                data={"action": "add"},
                expected=ExpectedResult(response_validators=[self.validate_rejoin]),
            ),
        ]
